(async()=>{
  const E=__echoes;
  const o={};
  E.cmd('giveSkill','warding_aura');
  E.cmd('giveSkill','sanctuary');
  E.cmd('giveSkill','restorative_wave');
  o.slots=E.state().skills.map(s=>s&&s.id);
  const grid={};
  for(const sk of ['mending_bolt','swift_mend','nova_bloom','sanctuary','spirit_bolt','warding_aura','guardian_bond','restorative_wave']){
    grid[sk]={};
    for(const n of ['sharpen','quicken','multiply','ascend','bounce','siphon','echo','detonate']){
      const p=E.cmd('buildPreview',sk,n);
      grid[sk][n]=p.error?('ERR:'+p.error):(p.verdict.state+(p.verdict.reason?('/'+p.verdict.reason):''));
    }
  }
  o.grid=grid;
  o.kitVerdicts={};
  for(const n of ['sharpen','quicken','multiply','ascend','bounce','siphon','echo','detonate']) o.kitVerdicts[n]=E.cmd('kitVerdict',n);
  o.prevMultiplyRW=E.cmd('buildPreview','restorative_wave','multiply');
  o.prevMultiplySanct=E.cmd('buildPreview','sanctuary','multiply');
  o.prevBounceAura=E.cmd('buildPreview','warding_aura','bounce');
  o.prevDetAura=E.cmd('buildPreview','warding_aura','detonate');
  o.prevEchoAura=E.cmd('buildPreview','warding_aura','echo');
  // socket the grey ones and confirm they are accepted with verdict grey
  E.cmd('grantNode','bounce'); E.cmd('grantNode','detonate'); E.cmd('grantNode','multiply'); E.cmd('grantNode','multiply');
  o.sockBounceAura=E.cmd('socket','warding_aura','bounce');
  o.sockDetAura=E.cmd('socket','warding_aura','detonate');
  o.sockMultSanct=E.cmd('socket','sanctuary','multiply');
  o.sockMultRW=E.cmd('socket','restorative_wave','multiply');
  const v=E.cmd('buildView');
  o.rows=v.skills.map(s=>({id:s.id,caps:s.caps,sockets:s.sockets,base:s.base,resolved:s.resolved}));
  o.denials=E.events.filter(e=>e.type==='socket_denied');
  return JSON.stringify(o);
})()
